import{_ as i,l,o as e,c as s,v as t,p as d,x as o,d as c,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"二义与左递归","description":"","frontmatter":{"title":"二义与左递归","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ambiguity-leftrec.md","filePath":"cs/ambiguity-leftrec.md","lastUpdated":1789023840000}'),n={name:"cs/ambiguity-leftrec.md"};function E(m,a,A,_,f,u){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="二义与左递归" tabindex="-1">二义与左递归 <a class="header-anchor" href="#二义与左递归" aria-label="Permalink to &quot;二义与左递归&quot;">​</a></h1><div class="epigraph"><p>同一终结串两棵推导树即二义；左递归让最左推导尚未读记号就展开自己，递归下降不停机。</p><footer>—— 据 Chomsky, 1959；龙书第 4 章整理</footer></div><p>上一课<a href="/cs/cfg-grammar">上下文无关文法</a>定义了产生式与推导树，并声明二义必须消、左递归留给分析器课。本课不重写 \\(G=(V,\\Sigma,P,S)\\)。缺口是两件会让下一课递归下降直接翻车的性质：悬空 else 这类二义，以及 \\(E\\to E+T\\) 这类左递归——后者要在文法上改写成右递归或循环，分析函数才停。FIRST 表下一课才系统算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二义：存在 \\(w\\) 有两棵不同的最左推导树。运算符优先级没写进文法时 <code>1+2*3</code> 两棵；<code>if</code>–<code>else</code> 与内层 <code>if</code> 配对两可。语义要唯一 AST，必须改产生式（分层 \\(E\\)、\\(T\\)、\\(F\\)）或在后课 LR 里用优先级声明消冲突。改写后语言应不变，树的形状按语言约定（左结合即左深树）。</p><p>左递归：\\(A\\stackrel{+}{\\Rightarrow}A\\alpha\\)。递归下降 <code>parseA</code> 先调 <code>parseA</code>，前瞻未消耗。消除：把 \\(A\\to A\\alpha\\mid\\beta\\) 改成 \\(A\\to\\beta A&#39;\\)，\\(A&#39;\\to\\alpha A&#39;\\mid\\varepsilon\\)（右递归），或写成 <code>parseA</code> 里先吃 \\(\\beta\\) 再循环吃 \\(\\alpha\\)。间接左递归要先代换。缺口是识别与改写，不是写完整下降器。</p><h3 id="左递归不是二义" tabindex="-1">左递归不是二义 <a class="header-anchor" href="#左递归不是二义" aria-label="Permalink to &quot;左递归不是二义&quot;">​</a></h3><p>左递归文法可以无二义（标准算术分层仍左递归）。二义文法也可以无左递归。两件事都碍分析，原因不同：一棵树 vs 停机。</p><p><span class="marginnote">龙书 4.3 节消除左递归、提取左公因子。Chomsky 层级不管二义；二义是分析器工程。Yacc 的优先级是后课 LR 的出口，本课以改写文法为主。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对二义：给两棵树，改分层或强制 else 绑定。对左递归：找出环 \\(A\\Rightarrow A\\alpha\\)，套标准改写。提取公因子 \\(A\\to\\alpha\\beta\\mid\\alpha\\gamma\\) 变成 \\(A\\to\\alpha B\\)，供后课 LL(1) 一眼看穿。</p>',11)),(e(),d(h,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22CFG%22%5D%20--%3E%20AMB%5B%22%E4%BA%8C%E4%B9%89%EF%BC%9F%E6%94%B9%E5%86%99%E6%88%96%E5%90%8E%E8%AF%BE%E6%B6%88%E5%86%B2%E7%AA%81%22%5D%0A%20%20CFG%20--%3E%20LR%5B%22%E5%B7%A6%E9%80%92%E5%BD%92%EF%BC%9F%E6%94%B9%E5%8F%B3%E9%80%92%E5%BD%92%E6%88%96%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20LR%20--%3E%20RD%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%80%92%E5%BD%92%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>语言是否仍同一：改写是语法变换，应保持 \\(L(G)\\)。优先级分层改变的是树，不是串集合——若原文法二义，串集合本就对多棵树。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>改写后非终结符变多，推导变长，AST 仍应压缩分层节点——<a href="/cs/ast">抽象语法树</a> 再丢。本课不建树。也不要把「有二义所以不是 CFG」：CFG 可以二义；无二义 CFG 才适合当程序语言定义。</p><p>左递归对 LR 无妨，对 LL 有妨。下一课是下降，故本课必须先改。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 FIRST/FOLLOW，不移进归约。不处理通用二义检测（那是不可判定的问题族边缘，点名：任意 CFG 是否二义不可判定，程序语言用手改）。后课默认：交给递归下降的文法无左递归、尽量无二义。下降器把最左推导写成函数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二义 = 一串多树；用分层或绑定规则消。</li><li>左递归使下降不停机；改写成右递归或循环。</li><li>两性质独立；下一课才写 <code>parseA</code>。</li><li>出处：Aho et al., 龙书第 4 章；Chomsky, 1959。</li></ul>',8))])}const T=i(n,[["render",E]]);export{b as __pageData,T as default};
